VStack(alignment: .leading, spacing: theme.spacing.space2) {
    Button {
        isOpen.toggle()
    } label: {
        MonarchAvatar(image: nil, name: {{user.name}}, size: .sm, isDecorative: true)
            .monarchMinimumHitTarget()
    }
    .buttonStyle(.plain)
    .accessibilityLabel("Account menu for " + {{user.name}})
    .accessibilityValue(isOpen ? "expanded" : "collapsed")
    if isOpen {
        VStack(alignment: .leading, spacing: 0) {
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                Text({{user.name}})
                    .monarchTextStyle(.bodyStrong)
                    .foregroundStyle(theme.colors.textDefault)
                Text(verbatim: {{user.email}})
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
            }
            .padding(.horizontal, theme.spacing.space3)
            .padding(.vertical, theme.spacing.space3)
            MonarchDivider()
            row("Profile", systemImage: "person") {}
            row("Settings", systemImage: "gearshape") {}
            MonarchDivider()
            sectionTitle("Switch workspace")
            row({{workspaces.0.name}}, initials: "N", isCurrent: workspace == {{workspaces.0.id}}) { workspace = {{workspaces.0.id}} }
            row({{workspaces.1.name}}, initials: "HL", isCurrent: workspace == {{workspaces.1.id}}) { workspace = {{workspaces.1.id}} }
            MonarchDivider()
            sectionTitle("Theme")
            row("Light", isCurrent: scheme == .light) { scheme = .light }
            row("Dark", isCurrent: scheme == .dark) { scheme = .dark }
            row("System", isCurrent: scheme == .system) { scheme = .system }
            MonarchDivider()
            row({{extraItem}}) {}
            MonarchDivider()
            row("Sign out", systemImage: "rectangle.portrait.and.arrow.right") {}
        }
        .frame(maxWidth: 280)
        .monarchElevation(.md, fill: \.bgRaised, in: RoundedRectangle(cornerRadius: theme.radius.lg, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: theme.radius.lg, style: .continuous).stroke(theme.colors.borderSubtle))
        .accessibilityElement(children: .contain)
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var workspace = {{workspace}}
@State private var scheme: MonarchSchemePreference = {{theme|case}}
@State private var isOpen = true

private func sectionTitle(_ title: String) -> some View {
    Text(title)
        .monarchTextStyle(.caption)
        .foregroundStyle(theme.colors.textMuted)
        .padding(.horizontal, theme.spacing.space3)
        .padding(.top, theme.spacing.space2)
}

/// One row of the menu: an icon or a workspace tile, the name, and a dot on the current choice.
private func row(
    _ title: String,
    systemImage: String? = nil,
    initials: String? = nil,
    isCurrent: Bool = false,
    action: @escaping () -> Void
) -> some View {
    Button(action: action) {
        HStack(spacing: theme.spacing.space2) {
            if let systemImage {
                MonarchIcon(systemName: systemImage, size: .sm)
                    .foregroundStyle(theme.colors.textMuted)
            }
            if let initials {
                Text(initials)
                    .monarchTextStyle(.caption)
                    .fontWeight(.semibold)
                    .foregroundStyle(theme.colors.infoStrong)
                    .frame(width: theme.spacing.space6, height: theme.spacing.space6)
                    .background(Circle().fill(theme.colors.infoSubtle))
            }
            Text(title)
                .monarchTextStyle(.bodySmall)
                .foregroundStyle(theme.colors.textDefault)
            Spacer(minLength: 0)
            if isCurrent {
                Circle()
                    .fill(theme.colors.accentSolid)
                    .frame(width: theme.spacing.space1_5, height: theme.spacing.space1_5)
            }
        }
        .padding(.horizontal, theme.spacing.space3)
        .frame(maxWidth: .infinity, minHeight: 44, alignment: .leading)
        .contentShape(Rectangle())
    }
    .buttonStyle(.plain)
    .accessibilityAddTraits(isCurrent ? .isSelected : [])
}

